+      if (request.type !== 'putArchiveEntries') throw new Error(`unexpected ${request.type}`);
+      attempt += 1;
+      if (attempt === 1) throw new Error('simulated durable write failure');
+      written.push(request.entries ?? []);
+      return { kind: 'putArchiveEntries' };
+    });
