+      expect(result.snapshot.displayName).toBe('Existing project');
+      expect(result.snapshot.walls).toHaveLength(1);
+      expect(result.snapshot.readOnly).toBe(false);
+      expect(result.snapshot.usedVfs).toBe('opfs-sahpool');
